from collections import Counter
def transform(g):
    out=[r[:] for r in g]; h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    for r in range(h-1):
        for c in range(w-1):
            if all(g[r+a][c+b]!=bg for a in (0,1) for b in (0,1)):
                for dr,dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
                    # first cell beyond block along (dr,dc) on the block's diagonal
                    if dr==1: rr=r+2
                    elif dr==-1: rr=r-1
                    else: rr=None
                    if dc==1: cc=c+2
                    elif dc==-1: cc=c-1
                    else: cc=None
                    # diagonal step: both coordinates move each step
                    # start step: nearest diagonal cell outside block
                    if dr==1 and dc==1: s=(r+2,c+2)
                    elif dr==1 and dc==-1: s=(r+2,c-1)
                    elif dr==-1 and dc==1: s=(r-1,c+2)
                    else: s=(r-1,c-1)
                    rr,cc=s
                    if not(0<=rr<h and 0<=cc<w): continue
                    col=g[rr][cc]
                    if col==bg: continue
                    # fill to edge
                    while 0<=rr<h and 0<=cc<w and g[rr][cc]!=bg:
                        out[rr][cc]=col; rr+=dr; cc+=dc
                    # continue filling bg cells with col? no—fill only contiguous same-color line cells.
    return out
